-- RLS with a transaction-bound signed context; no trust in plain org_id GUC.
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_organizations ON public.organizations TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_organizations ON public.organizations FOR SELECT TO hk_app USING(hk_security.allowed(id));
GRANT SELECT ON public.organizations TO hk_app;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_users ON public.users TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_users ON public.users FOR SELECT TO hk_app USING(id=hk_security.actor());
GRANT SELECT ON public.users TO hk_app;
ALTER TABLE public.assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assets FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_assets ON public.assets TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_assets ON public.assets FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.assets TO hk_app;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_audit_events ON public.audit_events TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_audit_events ON public.audit_events FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.audit_events TO hk_app;
ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_memberships ON public.memberships TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_memberships ON public.memberships FOR SELECT TO hk_app USING(user_id=hk_security.actor() AND active);
GRANT SELECT ON public.memberships TO hk_app;
ALTER TABLE public.evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.evidence FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_evidence ON public.evidence TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_evidence ON public.evidence FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.evidence TO hk_app;
ALTER TABLE public.model_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.model_versions FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_model_versions ON public.model_versions TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_model_versions ON public.model_versions FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.model_versions TO hk_app;
ALTER TABLE public.calculation_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.calculation_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_calculation_runs ON public.calculation_runs TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_calculation_runs ON public.calculation_runs FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.calculation_runs TO hk_app;
ALTER TABLE public.evidence_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.evidence_reviews FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_evidence_reviews ON public.evidence_reviews TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_evidence_reviews ON public.evidence_reviews FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.evidence_reviews TO hk_app;
ALTER TABLE public.model_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.model_reviews FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_model_reviews ON public.model_reviews TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_model_reviews ON public.model_reviews FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.model_reviews TO hk_app;
ALTER TABLE public.initiatives ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.initiatives FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_initiatives ON public.initiatives TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_initiatives ON public.initiatives FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.initiatives TO hk_app;
ALTER TABLE public.initiative_evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.initiative_evidence FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_initiative_evidence ON public.initiative_evidence TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_initiative_evidence ON public.initiative_evidence FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.initiative_evidence TO hk_app;
ALTER TABLE public.transitions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transitions FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_transitions ON public.transitions TO hk_owner USING(true) WITH CHECK(true);
CREATE POLICY read_transitions ON public.transitions FOR SELECT TO hk_app USING(hk_security.allowed(org_id));
GRANT SELECT ON public.transitions TO hk_app;
CREATE POLICY auth_principals ON public.users FOR SELECT TO hk_authenticator USING(true);
CREATE POLICY insert_assets ON public.assets FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['admin','engineer']));
GRANT INSERT ON public.assets TO hk_app;
CREATE POLICY insert_evidence ON public.evidence FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,CASE kind WHEN 'financial_report' THEN ARRAY['economist'] WHEN 'approval_memo' THEN ARRAY['manager'] WHEN 'outcome_report' THEN ARRAY['auditor'] ELSE ARRAY['engineer'] END) AND created_by=hk_security.actor());
GRANT INSERT ON public.evidence TO hk_app;
CREATE POLICY insert_model_versions ON public.model_versions FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['engineer']) AND created_by=hk_security.actor());
GRANT INSERT ON public.model_versions TO hk_app;
CREATE POLICY insert_evidence_reviews ON public.evidence_reviews FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['auditor']) AND actor_id=hk_security.actor() AND EXISTS(SELECT 1 FROM public.evidence e WHERE e.org_id=evidence_reviews.org_id AND e.id=evidence_id AND e.created_by<>hk_security.actor()));
GRANT INSERT ON public.evidence_reviews TO hk_app;
CREATE POLICY insert_model_reviews ON public.model_reviews FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['auditor']) AND actor_id=hk_security.actor() AND EXISTS(SELECT 1 FROM public.model_versions m WHERE m.org_id=model_reviews.org_id AND m.id=model_id AND m.created_by<>hk_security.actor()));
GRANT INSERT ON public.model_reviews TO hk_app;
CREATE POLICY insert_calculation_runs ON public.calculation_runs FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['engineer']) AND created_by=hk_security.actor() AND EXISTS(SELECT 1 FROM public.model_reviews mr WHERE mr.org_id=calculation_runs.org_id AND mr.model_id=calculation_runs.model_id AND mr.accepted) AND EXISTS(SELECT 1 FROM public.evidence_reviews er WHERE er.org_id=calculation_runs.org_id AND er.evidence_id=calculation_runs.evidence_id AND er.accepted));
GRANT INSERT ON public.calculation_runs TO hk_app;
CREATE POLICY insert_initiatives ON public.initiatives FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['engineer']) AND created_by=hk_security.actor() AND state='draft' AND revision=0 AND engineer_approver IS NULL AND finance_approver IS NULL);
GRANT INSERT ON public.initiatives TO hk_app;
CREATE POLICY insert_initiative_evidence ON public.initiative_evidence FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id,ARRAY['engineer','economist','manager','auditor']) AND EXISTS(SELECT 1 FROM public.initiatives i JOIN public.evidence e ON e.org_id=i.org_id AND e.asset_id=i.asset_id JOIN public.evidence_reviews r ON r.evidence_id=e.id AND r.org_id=e.org_id WHERE i.id=initiative_id AND i.org_id=initiative_evidence.org_id AND e.id=initiative_evidence.evidence_id AND r.accepted AND i.state<>'verified' AND (e.kind NOT IN ('engineering_report','financial_report','outcome_report') OR e.payload->>'run_id'=i.run_id)));
GRANT INSERT ON public.initiative_evidence TO hk_app;
CREATE POLICY insert_transitions ON public.transitions FOR INSERT TO hk_app WITH CHECK(hk_security.allowed(org_id) AND actor_id=hk_security.actor() AND EXISTS(SELECT 1 FROM public.initiatives i WHERE i.org_id=transitions.org_id AND i.id=initiative_id AND i.revision=transitions.revision AND i.state=to_state));
GRANT INSERT ON public.transitions TO hk_app;
CREATE POLICY update_initiatives ON public.initiatives FOR UPDATE TO hk_app USING(hk_security.allowed(org_id)) WITH CHECK(hk_security.allowed(org_id));
GRANT UPDATE(state,revision,engineer_approver,finance_approver) ON public.initiatives TO hk_app;
ALTER TABLE public.assets ADD CONSTRAINT assets_tenant_id UNIQUE(org_id,id);
ALTER TABLE public.evidence ADD CONSTRAINT evidence_tenant_id UNIQUE(org_id,id);
ALTER TABLE public.model_versions ADD CONSTRAINT model_versions_tenant_id UNIQUE(org_id,id);
ALTER TABLE public.calculation_runs ADD CONSTRAINT calculation_runs_tenant_id UNIQUE(org_id,id);
ALTER TABLE public.initiatives ADD CONSTRAINT initiatives_tenant_id UNIQUE(org_id,id);
ALTER TABLE public.evidence ADD CONSTRAINT evidence_tenant_asset_id UNIQUE(org_id,asset_id,id);
ALTER TABLE public.model_versions ADD CONSTRAINT model_versions_tenant_asset_id UNIQUE(org_id,asset_id,id);
ALTER TABLE public.calculation_runs ADD CONSTRAINT calculation_runs_tenant_asset_id UNIQUE(org_id,asset_id,id);
ALTER TABLE public.evidence ADD CONSTRAINT evidence_asset_id_tenant_fk FOREIGN KEY(org_id,asset_id) REFERENCES public.assets(org_id,id);
ALTER TABLE public.model_versions ADD CONSTRAINT model_versions_asset_id_tenant_fk FOREIGN KEY(org_id,asset_id) REFERENCES public.assets(org_id,id);
ALTER TABLE public.evidence_reviews ADD CONSTRAINT evidence_reviews_evidence_id_tenant_fk FOREIGN KEY(org_id,evidence_id) REFERENCES public.evidence(org_id,id);
ALTER TABLE public.model_reviews ADD CONSTRAINT model_reviews_model_id_tenant_fk FOREIGN KEY(org_id,model_id) REFERENCES public.model_versions(org_id,id);
ALTER TABLE public.calculation_runs ADD CONSTRAINT calculation_runs_asset_id_tenant_fk FOREIGN KEY(org_id,asset_id) REFERENCES public.assets(org_id,id);
ALTER TABLE public.initiatives ADD CONSTRAINT initiatives_asset_id_tenant_fk FOREIGN KEY(org_id,asset_id) REFERENCES public.assets(org_id,id);
ALTER TABLE public.initiative_evidence ADD CONSTRAINT initiative_evidence_initiative_id_tenant_fk FOREIGN KEY(org_id,initiative_id) REFERENCES public.initiatives(org_id,id);
ALTER TABLE public.initiative_evidence ADD CONSTRAINT initiative_evidence_evidence_id_tenant_fk FOREIGN KEY(org_id,evidence_id) REFERENCES public.evidence(org_id,id);
ALTER TABLE public.transitions ADD CONSTRAINT transitions_initiative_id_tenant_fk FOREIGN KEY(org_id,initiative_id) REFERENCES public.initiatives(org_id,id);
ALTER TABLE public.calculation_runs ADD CONSTRAINT calculation_runs_model_id_asset_fk FOREIGN KEY(org_id,asset_id,model_id) REFERENCES public.model_versions(org_id,asset_id,id);
ALTER TABLE public.calculation_runs ADD CONSTRAINT calculation_runs_evidence_id_asset_fk FOREIGN KEY(org_id,asset_id,evidence_id) REFERENCES public.evidence(org_id,asset_id,id);
ALTER TABLE public.initiatives ADD CONSTRAINT initiatives_run_id_asset_fk FOREIGN KEY(org_id,asset_id,run_id) REFERENCES public.calculation_runs(org_id,asset_id,id);
ALTER TABLE public.memberships ADD CONSTRAINT known_role CHECK(role IN ('engineer','economist','manager','auditor','admin','viewer'));
ALTER TABLE public.evidence_reviews ADD CONSTRAINT single_evidence_review UNIQUE(org_id,evidence_id);
ALTER TABLE public.model_reviews ADD CONSTRAINT single_model_review UNIQUE(org_id,model_id);
ALTER TABLE public.transitions ADD CONSTRAINT unique_transition_revision UNIQUE(org_id,initiative_id,revision);
ALTER TABLE public.audit_events ADD CONSTRAINT valid_audit_seq CHECK(seq>0 AND timestamp_ms>0);
